<?php if($pages>1): ?><nav class="staff-pagination" aria-label="Navigasi halaman"><?php $make_url=function($number) use($base,$params){return $base.'?'.http_build_query(array_merge($params,array('page'=>$number)));}; ?><?php if($page>1): ?><a href="<?= html_escape($make_url($page-1)) ?>" aria-label="Halaman sebelumnya">←</a><?php endif; ?><?php if($page>3): ?><a href="<?= html_escape($make_url(1)) ?>">1</a><?php if($page>4): ?><span aria-hidden="true">…</span><?php endif; ?><?php endif; ?><?php for($n=max(1,$page-2);$n<=min($pages,$page+2);$n++): ?><a href="<?= html_escape($make_url($n)) ?>" class="<?= $n===$page?'active':'' ?>" <?= $n===$page?'aria-current="page"':'' ?>><?= $n ?></a><?php endfor; ?><?php if($page<$pages-2): ?><?php if($page<$pages-3): ?><span aria-hidden="true">…</span><?php endif; ?><a href="<?= html_escape($make_url($pages)) ?>"><?= $pages ?></a><?php endif; ?><?php if($page<$pages): ?><a href="<?= html_escape($make_url($page+1)) ?>" aria-label="Halaman berikutnya">→</a><?php endif; ?></nav><?php endif; ?>
